namespace Hfd.Base.Contract.Internals;

public static class PasswordHelper
{
	/// <summary>
	///     Hash a password using the OpenBSD BCrypt scheme and a salt generated by BCrypt.Net.BCrypt.GenerateSalt.
	/// </summary>
	/// <param name="text">The password to hash.</param>
	/// <returns>The hashed password.</returns>
	public static string Hash(this string text)
	{
		return BCrypt.Net.BCrypt.HashPassword(text);
	}

	/// <summary>
	///     Verifies that the hash of the given text matches the provided hash
	/// </summary>
	/// <param name="text">The text to verify.</param>
	/// <param name="hash">The previously-hashed password.</param>
	/// <returns></returns>
	public static bool Verify(this string text, string hash)
	{
		return BCrypt.Net.BCrypt.Verify(text, hash);
	}
}